import{_ as o,a as t,c as a,ac as n}from"./chunks/framework.BSuaGltH.js";const d=JSON.parse('{"title":"第二册：实践与进步 · 单元 3 语法总结 · 时间、原因与让步从句至间接引语与视角转换","description":"L49–L72 规则、例句、易错点。","frontmatter":{"title":"第二册：实践与进步 · 单元 3 语法总结 · 时间、原因与让步从句至间接引语与视角转换","description":"L49–L72 规则、例句、易错点。","splitFrom":"life/english/new-concept/book-2/unit-03/grammar.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"句法与表达查阅","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第二册：实践与进步 · 单元 3 语法总结","summary":"L49–L72 规则、例句、易错点。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · 单元 3 语法总结 · 叙事中的时态与衔接至被动语态与信息重点","link":"/life/english/new-concept/book-2/unit-03/grammar-part-01"},"next":{"text":"第二册：实践与进步 · 单元 3 语法总结 · 非真实条件句至分词修饰与逻辑主语","link":"/life/english/new-concept/book-2/unit-03/grammar-part-03"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · 单元 3 语法总结 · 叙事中的时态与衔接至被动语态与信息重点","link":"/life/english/new-concept/book-2/unit-03/grammar-part-01"},"next":{"text":"第二册：实践与进步 · 单元 3 语法总结 · 非真实条件句至分词修饰与逻辑主语","link":"/life/english/new-concept/book-2/unit-03/grammar-part-03"}},"headers":[],"relativePath":"life/english/new-concept/book-2/unit-03/grammar-part-02.md","filePath":"life/english/new-concept/book-2/unit-03/grammar-part-02.md"}'),r={name:"life/english/new-concept/book-2/unit-03/grammar-part-02.md"};function s(i,e,l,p,h,g){return t(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="第二册-实践与进步-·-单元-3-语法总结-·-时间、原因与让步从句至间接引语与视角转换" tabindex="-1">第二册：实践与进步 · 单元 3 语法总结 · 时间、原因与让步从句至间接引语与视角转换 <a class="header-anchor" href="#第二册-实践与进步-·-单元-3-语法总结-·-时间、原因与让步从句至间接引语与视角转换" aria-label="Permalink to &quot;第二册：实践与进步 · 单元 3 语法总结 · 时间、原因与让步从句至间接引语与视角转换&quot;">​</a></h1><p><a href="/life/english/new-concept/book-2/unit-03/grammar">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-2/unit-03/overview">单元导读</a> · <a href="/life/english/new-concept/book-2/unit-03/grammar">单元语法总结</a> · <a href="/life/english/new-concept/book-2/unit-03/vocabulary">单元单词与短语</a> · <a href="/life/english/new-concept/book-2/unit-03/review">单元复习与自测</a></p><h2 id="时间、原因与让步从句" tabindex="-1">时间、原因与让步从句 <a class="header-anchor" href="#时间、原因与让步从句" aria-label="Permalink to &quot;时间、原因与让步从句 {#时间、原因与让步从句}&quot;">​</a></h2><p>状语从句为主句提供时间、原因、条件或让步背景。连接词不仅连接形式，也表达逻辑：because 给原因，although 表示让步，while 可以表示同时或对照，until 标记持续的终点。英语通常不把 although 与 but、because 与 so 成对放在同一个复合句中。从句置前时一般用逗号隔开；选连接词前先判断两件事之间的实际关系。本课应用：No sooner had ... than ... 可强调紧接发生，并在 no sooner 前置时倒装；普通 after 句则无需这种语序，初学可先用 as soon as。</p><p>状语从句为主句提供时间、原因、条件或让步背景。连接词不仅连接形式，也表达逻辑：because 给原因，although 表示让步，while 可以表示同时或对照，until 标记持续的终点。英语通常不把 although 与 but、because 与 so 成对放在同一个复合句中。从句置前时一般用逗号隔开；选连接词前先判断两件事之间的实际关系。本课应用：although 表承认损失同时提出改善，不能与 but 在同一复合句中配对。因祸得福是评价，必须由后续事实支撑。</p><p><strong>L54 原创例句：</strong> As soon as I opened the jar, jam ran over my fingers.</p><p>我一打开罐子，果酱就流到了手指上。</p><p><strong>L58 原创例句：</strong> Although the flood damaged the garden, it led to better drainage.</p><p>虽然洪水损坏了花园，但它促成了更好的排水设施。</p><p><strong>易错：</strong> run 的过去式是 ran，过去分词才是 run；不能在简单过去叙事中写 jam run。</p><p>Although ..., but ... 在标准英语中不作这种成对连接；保留一个连接词。</p><p><a href="/life/english/new-concept/book-2/unit-03/lesson-054">Lesson 54</a> · <a href="/life/english/new-concept/book-2/unit-03/lesson-058">Lesson 58</a></p><h2 id="一般过去时与事件顺序" tabindex="-1">一般过去时与事件顺序 <a class="header-anchor" href="#一般过去时与事件顺序" aria-label="Permalink to &quot;一般过去时与事件顺序 {#一般过去时与事件顺序}&quot;">​</a></h2><p>一般过去时把动作放在已经结束的过去时间内，肯定句用动词过去式；疑问和否定借助 did 后，实义动词恢复原形。be 的过去式是 was/were，不再加 did。叙事中连续的过去式通常按出现顺序推进情节；单凭一句过去式不能推断动作持续多久。先确定时间范围，再选择动词形式，不要把汉语中的“了”机械地翻译成完成时。本课应用：used to believe 表过去常持有的看法，现在已改变；once believed 则只说明曾相信，不一定强调长期习惯。</p><p><strong>L55 原创例句：</strong> People once believed that the field contained gold.</p><p>人们曾相信那片田地含有黄金。</p><p><strong>易错：</strong> gold 是不可数物质名词，通常不写 a gold；a piece of gold 才表示一块。</p><p><a href="/life/english/new-concept/book-2/unit-03/lesson-055">Lesson 55</a></p><h2 id="比较级与比较范围" tabindex="-1">比较级与比较范围 <a class="header-anchor" href="#比较级与比较范围" aria-label="Permalink to &quot;比较级与比较范围 {#比较级与比较范围}&quot;">​</a></h2><p>比较两者时通常用比较级和 than；在明确的三者或更多成员中选出极值时通常用最高级。短形容词多加 -er/-est，较长形容词多用 more/most，good 与 bad 则是不规则变化。as ... as 中间用原级，否定形式表示不及。比较对象应属于同一类，范围和参照点必须清楚，不能只看到中文“最”就省掉比较范围。本课应用：much faster 表差异大，a little faster 表差异小；不能说 very faster。比较速度时，时间、距离和单位必须对应。</p><p><strong>L56 原创例句：</strong> The new car was much faster than the team&#39;s previous model.</p><p>新车比车队之前的车型快得多。</p><p><strong>易错：</strong> more faster 重复比较标记；用 faster 或 much faster。</p><p><a href="/life/english/new-concept/book-2/unit-03/lesson-056">Lesson 56</a></p><h2 id="情态动词的意义与形式" tabindex="-1">情态动词的意义与形式 <a class="header-anchor" href="#情态动词的意义与形式" aria-label="Permalink to &quot;情态动词的意义与形式 {#情态动词的意义与形式}&quot;">​</a></h2><p>can、could、may、might、must 等情态动词后接动词原形，否定一般直接加 not，不需要 do。它们可能表示能力、许可、义务或推测，必须根据上下文区分；could 不总是过去时间，也能表示委婉请求或较弱的可能性。must not 表示禁止，do not have to 表示没有必要，二者意义完全不同。判断语气时先问说话人在提出要求还是评价证据。本课应用：Can I help ...? 在服务场景中是主动提供帮助，不是要求顾客证明自己需要帮助。Would you like ...? 通常比直接命令更委婉。</p><p><strong>L57 原创例句：</strong> Would you like to see a different size?</p><p>您想看看另一个尺寸吗？</p><p><strong>易错：</strong> Would you like seeing 通常不是提出这次邀请的用法；用 Would you like to see。</p><p><a href="/life/english/new-concept/book-2/unit-03/lesson-057">Lesson 57</a></p><h2 id="动词、宾语与补足语" tabindex="-1">动词、宾语与补足语 <a class="header-anchor" href="#动词、宾语与补足语" aria-label="Permalink to &quot;动词、宾语与补足语 {#动词、宾语与补足语}&quot;">​</a></h2><p>英语陈述句通常先交代主语和谓语，再放宾语及必要的补足语。部分动词可以带人和物两个宾语，如 give somebody something，也可改为 give something to somebody；buy 常用 for。并不是所有动词都支持这两种结构，explain 通常用 explain something to somebody。补足语则进一步说明宾语的身份或状态，不能与表示地点和时间的附加信息混为一谈。本课应用：let the cat enter 使用不带 to 的原形；allow the cat to enter 则需要 to。两者意思接近但结构不能直接混搭。</p><p>英语陈述句通常先交代主语和谓语，再放宾语及必要的补足语。部分动词可以带人和物两个宾语，如 give somebody something，也可改为 give something to somebody；buy 常用 for。并不是所有动词都支持这两种结构，explain 通常用 explain something to somebody。补足语则进一步说明宾语的身份或状态，不能与表示地点和时间的附加信息混为一谈。本课应用：made the animal move 用原形 move；被动 was made to move 则恢复 to。不要把主动使役结构机械搬到被动句。</p><p><strong>L59 原创例句：</strong> The new flap lets the cat enter without waking us.</p><p>新的宠物门让猫可以进来而不吵醒我们。</p><p><strong>L65 原创例句：</strong> The keeper made the elephant move towards a basket of fruit.</p><p>饲养员使大象朝一篮水果走去。</p><p><strong>易错：</strong> lets the cat to enter 多了 to；allows the cat enter 则少了 to。</p><p>made the elephant to move 在主动句中多余 to；被动才常用 was made to move。</p><p><a href="/life/english/new-concept/book-2/unit-03/lesson-059">Lesson 59</a> · <a href="/life/english/new-concept/book-2/unit-03/lesson-065">Lesson 65</a></p><h2 id="将来表达与安排" tabindex="-1">将来表达与安排 <a class="header-anchor" href="#将来表达与安排" aria-label="Permalink to &quot;将来表达与安排 {#将来表达与安排}&quot;">​</a></h2><p>will 加动词原形可表达预测、意愿或当场决定；be going to 常表达已有打算或基于眼前证据的判断；现在进行时可描述已经落实的个人安排。表示时刻表也可用一般现在时。它们并不是严格的一对一中文翻译。时间和条件状语从句谈将来时，通常用现在时配合主句的将来表达，而不是把每个动词都加上 will。本课应用：will meet 可表达预测，不自动意味着确定事实；may meet 更谨慎。预测是否可信取决于来源，时态本身不提供证据。</p><p><strong>L60 原创例句：</strong> The guide predicted that we would see clear skies by evening.</p><p>向导预测，到傍晚我们会看到晴朗天空。</p><p><strong>易错：</strong> predict 不等于 promise；前者是判断未来，后者是作出承担义务的承诺。</p><p><a href="/life/english/new-concept/book-2/unit-03/lesson-060">Lesson 60</a></p><h2 id="间接引语与视角转换" tabindex="-1">间接引语与视角转换 <a class="header-anchor" href="#间接引语与视角转换" aria-label="Permalink to &quot;间接引语与视角转换 {#间接引语与视角转换}&quot;">​</a></h2><p>转述他人的话需要调整人称、时间和地点参照。主句为过去时且从过去视角回顾时，从句常相应后移时态；内容仍然有效或属于一般事实时，也可以保留现在时。陈述用 that 从句，是否问句用 if/whether，特殊疑问保留疑问词。转述疑问一律采用陈述语序，不保留原问句的助动词倒装；不能只换引号而不考虑说话视角。本课应用：asked me not to repeat 把否定放在 to 前，表示请我不要重复；did not ask me to repeat 则只是没有提出重复请求，意义不同。</p><p><strong>L63 原创例句：</strong> The host asked me not to repeat the joke.</p><p>主持人请我不要再讲那个笑话。</p><p><strong>易错：</strong> asked me to not repeat 有时可见，但常规教学优先 not to repeat；did not ask 与 asked not 不同。</p><p><a href="/life/english/new-concept/book-2/unit-03/lesson-063">Lesson 63</a></p>',53)])])}const m=o(r,[["render",s]]);export{d as __pageData,m as default};
